// LW1.USE-1: the parse-site census across the six consumers.
//
// A parse site is one of:
//   IMPORT-VJ        an import/export edge from `@mkbabb/value.js` or a subpath
//   CALL-PARSE       a call of a value.js parse entry (an exported `parse*`)
//   CALL-SERIALIZE   a call of a value.js serialize/format entry
//   IMPORT-PT/CALL-PT      `@mkbabb/parse-that` edge / call of a binding from it
//   IMPORT-BBNF/CALL-BBNF  `@mkbabb/bbnf-lang` edge / call of a binding from it
//   GENERATED        an import edge to a module whose text says it was generated by bbnf
//   GRAMMAR          a `.bbnf` file (one row, line 1, `detail` = its line count)
//   REGEX            a regex literal or a `RegExp(` construction in code
// Scope classifies the file (src, test, script, bench, demo, config).
// Every row is read at the HEADS.tsv commit, so the census regenerates exactly.
import { readHeads, lsTree, show, tsv, mask, scriptOnly, lineOf } from "./lib.mjs";

const SOURCE = /\.(ts|tsx|mts|cts|js|mjs|cjs|vue)$/;
const SKIP = /(^|\/)(node_modules|dist|docs|evidence|records|\.lighthouseci|\.worktrees|coverage|playwright-report|test-results|vendor)\//;
const GENERATED_SKIP = /\.d\.ts$|\.min\.js$/;

export function scopeOf(file) {
    if (/(^|\/)(test|tests|__tests__|e2e|spec)\//.test(file) || /\.(test|spec)\.[cm]?[jt]sx?$/.test(file)) return "test";
    if (/(^|\/)bench\//.test(file) || /\.bench\.[cm]?[jt]s$/.test(file)) return "bench";
    if (/(^|\/)(scripts|tools|xtask)\//.test(file)) return "script";
    if (/(^|\/)(demo|playground|examples?)\//.test(file)) return "demo";
    if (/(^|\/)[^/]*\.config\.[cm]?[jt]s$|(^|\/)\.[^/]*rc\.[cm]?js$|\.cjs$/.test(file) && !/\/src\//.test(file)) return "config";
    return "src";
}

/** value.js's parse and serialize entries, read from value.js's own source at its pin. */
export function valueEntries(vj) {
    const parse = new Set();
    const serialize = new Set();
    for (const f of lsTree(vj.path, vj.sha)) {
        if (!/^src\/.*\.ts$/.test(f) || /\.d\.ts$/.test(f)) continue;
        const t = mask(show(vj.path, vj.sha, f)).code;
        for (const m of t.matchAll(/export\s+(?:async\s+)?(?:function\*?|const|let)\s+((?:parse|serialize|format)[A-Z]\w*)/g)) {
            (m[1].startsWith("parse") ? parse : serialize).add(m[1]);
        }
    }
    return { parse, serialize };
}

const IMPORT_RE = /\b(import|export)\s+(type\s+)?([\s\S]*?)\s*\bfrom\s*(["'])([^"']+)\4|\bimport\s*\(\s*(["'])([^"']+)\6\s*\)|\bimport\s+(["'])([^"']+)\8/g;

function family(spec, repo) {
    if (/^@mkbabb\/value\.js(\/|$)/.test(spec)) return "VJ";
    if (/^@mkbabb\/parse-that(\/|$)/.test(spec)) return "PT";
    if (/^@mkbabb\/bbnf-lang(\/|$)|^bbnf-lang(\/|$)/.test(spec)) return "BBNF";
    if (repo === "value.js" && /(^|\/)generated\/(grammar|color)(\.js)?$/.test(spec)) return "GENERATED";
    if (repo === "value.js" && !spec.startsWith("@") && !/^[a-z]/.test(spec)) return "VJ-INTERNAL";
    if (repo === "value.js" && /^@(src|\/)/.test(spec)) return "VJ-INTERNAL";
    return null;
}

/** Value bindings (local names) of an import clause; type-only specifiers dropped. */
function bindings(clause, typeOnly) {
    if (typeOnly || !clause) return [];
    const out = [];
    const named = clause.match(/\{([\s\S]*)\}/);
    if (named) {
        for (const part of named[1].split(",")) {
            const p = part.trim();
            if (!p || /^type\s/.test(p)) continue;
            const [imported, local] = p.split(/\s+as\s+/).map((s) => s.trim());
            out.push({ imported, local: local ?? imported });
        }
    }
    const def = clause.replace(/\{[\s\S]*\}/, "").replace(/\*\s+as\s+(\w+)/, (_, ns) => {
        out.push({ imported: "*", local: ns });
        return "";
    });
    const d = def.replace(/,/g, " ").trim();
    if (/^[A-Za-z_$][\w$]*$/.test(d)) out.push({ imported: "default", local: d });
    return out;
}

export function censusRepo(head, entries) {
    const rows = [];
    for (const file of lsTree(head.path, head.sha)) {
        if (SKIP.test(file)) continue;
        if (file.endsWith(".bbnf")) {
            const t = show(head.path, head.sha, file);
            rows.push({ repo: head.repo, sha: head.sha.slice(0, 12), file, line: 1, scope: scopeOf(file), kind: "GRAMMAR", module: "", binding: "", detail: `${t.split("\n").length} lines` });
            continue;
        }
        if (!SOURCE.test(file) || GENERATED_SKIP.test(file)) continue;
        const raw = show(head.path, head.sha, file);
        if (/^\s*\/\/ GENERATED by @mkbabb\/bbnf-lang/.test(raw)) {
            rows.push({ repo: head.repo, sha: head.sha.slice(0, 12), file, line: 1, scope: scopeOf(file), kind: "GENERATED-MODULE", module: "", binding: "", detail: `${raw.length} bytes` });
            continue;
        }
        const text = scriptOnly(file, raw);
        const { code, bare, regexes } = mask(text);
        const scope = scopeOf(file);
        const base = { repo: head.repo, sha: head.sha.slice(0, 12), file, scope };
        const callable = new Map(); // local -> {kind, imported, module}
        for (const m of code.matchAll(IMPORT_RE)) {
            const spec = m[5] ?? m[7] ?? m[9];
            const fam = family(spec, head.repo);
            if (!fam) continue;
            const line = lineOf(code, m.index);
            const typeOnly = Boolean(m[2]);
            const bs = m[5] ? bindings(m[3], typeOnly) : [];
            if (fam !== "VJ-INTERNAL") {
                rows.push({ ...base, line, kind: fam === "GENERATED" ? "GENERATED" : `IMPORT-${fam}`, module: spec, binding: bs.map((b) => b.local).join(" "), detail: typeOnly ? "type-only" : m[1] === "export" ? "re-export" : m[6] ? "dynamic" : "" });
            }
            for (const b of bs) {
                if (m[1] === "export") continue;
                if (fam === "VJ" || fam === "VJ-INTERNAL") {
                    if (entries.parse.has(b.imported)) callable.set(b.local, { kind: "CALL-PARSE", imported: b.imported, module: spec });
                    else if (entries.serialize.has(b.imported)) callable.set(b.local, { kind: "CALL-SERIALIZE", imported: b.imported, module: spec });
                } else if (fam === "PT" || fam === "BBNF" || fam === "GENERATED") {
                    callable.set(b.local, { kind: fam === "GENERATED" ? "CALL-GENERATED" : `CALL-${fam}`, imported: b.imported, module: spec });
                }
            }
        }
        // a tool reached by path, not by import (value.js's gen-grammar spawns `bbnf gen`)
        const importAt = new Set([...code.matchAll(IMPORT_RE)].map((m) => lineOf(code, m.index)));
        for (const m of code.matchAll(/["'`][^"'`\n]*@mkbabb\/(bbnf-lang|parse-that)[^"'`\n]*["'`]/g)) {
            const line = lineOf(code, m.index);
            if (importAt.has(line)) continue;
            rows.push({ ...base, line, kind: m[1] === "bbnf-lang" ? "REF-BBNF" : "REF-PT", module: `@mkbabb/${m[1]}`, binding: "", detail: m[0].slice(1, -1) });
        }
        if (callable.size) {
            const names = [...callable.keys()].map((s) => s.replace(/\$/g, "\\$")).join("|");
            const callRe = new RegExp(`(?<![\\w$.])(${names})\\s*(?:<[^<>()]*>)?\\s*\\(`, "g");
            for (const m of bare.matchAll(callRe)) {
                const c = callable.get(m[1]);
                const line = lineOf(bare, m.index);
                // an `function parseX(` declaration is a definition, not a call
                if (/\bfunction\s*\*?\s*$/.test(bare.slice(Math.max(0, m.index - 12), m.index))) continue;
                rows.push({ ...base, line, kind: c.kind, module: c.module, binding: m[1], detail: c.imported === m[1] ? "" : `as ${c.imported}` });
            }
        }
        for (const r of regexes) {
            const lit = text.slice(r.start, r.end);
            rows.push({ ...base, line: lineOf(text, r.start), kind: "REGEX", module: "", binding: "", detail: `literal ${lit.length}ch` });
        }
        for (const m of bare.matchAll(/(?<![\w$.])(?:new\s+)?RegExp\s*\(/g)) {
            rows.push({ ...base, line: lineOf(bare, m.index), kind: "REGEX", module: "", binding: "", detail: "RegExp()" });
        }
    }
    return rows;
}

export const CENSUS_HEADER = ["repo", "sha", "file", "line", "scope", "kind", "module", "binding", "detail"];

export function census() {
    const heads = readHeads();
    const vj = heads.find((h) => h.repo === "value.js");
    const entries = valueEntries(vj);
    const rows = heads.flatMap((h) => censusRepo(h, entries));
    rows.sort((a, b) => a.repo.localeCompare(b.repo) || a.file.localeCompare(b.file) || a.line - b.line || a.kind.localeCompare(b.kind) || a.binding.localeCompare(b.binding));
    return { rows, entries, heads };
}
